// Selected official application controller; generated by prepare_partner_detail_window_ui.py.
namespace Zjcs.Official.PartnersUI
{
using Object = UnityEngine.Object;
using Zjcs.Official.ProfessionUI;
using Zjcs.Official.WorldUI;
using MultiLanguageText = Zjcs.Official.WorldUI.WorldMultiLanguageText;
using System;
using System.Collections.Generic;
using System.Threading;
using Cysharp.Threading.Tasks;
using UnityEngine;
using UnityEngine.Events;
using UnityEngine.UI;

public class NpcDetailLiveItem : MonoBehaviour
{
	[SerializeField]
	private Component mNpcLiveGraphic;

	[SerializeField]
	private RectTransform mNpcLiveRect;

	[SerializeField]
	private SkeletonGraphicAnimSequence mNpcLiveAnimSequence;

	[SerializeField]
	private Button mNpcLiveClickBtn;

	[SerializeField]
	private List<NpcDetailLiveEffectInfo> mClickEffectInfoList;

	[SerializeField]
	private List<NpcDetailLiveEffectInfo> mIdleEffectInfoList;

	private PartnerDetailPresentationInfo mNpcInfo;

	private PartnerDetailResourceBag mDisposableBag;

	private CancellationTokenSource mClickEffectCts;

	private CancellationTokenSource mIdleEffectCts;


	public int NpcId => mNpcInfo?.Id ?? 0;

    private IPartnerDetailLiveItemServices services;
    public void Configure(IPartnerDetailLiveItemServices value)
    { services = value ?? throw new System.ArgumentNullException(nameof(value)); }

	private void Awake()
	{

		mDisposableBag = new PartnerDetailResourceBag();
	}

	private void OnDestroy()
	{
		mDisposableBag.Dispose();
	}

	private void OnEnable()
	{




		((UnityEvent)mNpcLiveClickBtn.onClick).AddListener((UnityAction)OnNpcLiveClicked);
		ShowClickEffects(isShow: false);
		if ((Object)(object)mNpcLiveGraphic != (Object)null)
		{
			if (services.HasSkeletonData(mNpcLiveGraphic))
			{
				services.Initialize(mNpcLiveGraphic, true);
			}
			services.Resolve(mNpcLiveGraphic).OnAnimationRebuild += OnAnimationRebuild;
		}
	}

	private void OnDisable()
	{








		((UnityEvent)mNpcLiveClickBtn.onClick).RemoveListener((UnityAction)OnNpcLiveClicked);
		if ((Object)(object)mNpcLiveGraphic != (Object)null)
		{
			services.Resolve(mNpcLiveGraphic).OnAnimationRebuild -= OnAnimationRebuild;
			if (services.Resolve(mNpcLiveGraphic).AnimationState != null)
			{
				services.Resolve(mNpcLiveGraphic).AnimationState.Start -= OnSpineAnimStart;
				services.Resolve(mNpcLiveGraphic).AnimationState.Complete -= OnSpineAnimComplete;
			}
		}
		DisposeClickEffectCts();
		DisposeIdleEffectCts();
	}

	private void OnAnimationRebuild(IPartnerSequenceGraphic animated)
	{








		IPartnerSequenceAnimationState animationState = services.Resolve(mNpcLiveGraphic).AnimationState;
		if (animationState != null)
		{
			animationState.Start -= OnSpineAnimStart;
			animationState.Start += OnSpineAnimStart;
			animationState.Complete -= OnSpineAnimComplete;
			animationState.Complete += OnSpineAnimComplete;
			IPartnerSequenceTrack current = animationState.GetCurrent(0);
			if (current != null && current.Animation != null)
			{
				OnSpineAnimStart(current);
			}
		}
	}

	private void OnSpineAnimComplete(IPartnerSequenceTrack entry)
	{
		string name = entry.Animation.Name;
		if (!(name == "idle_01"))
		{
			_ = name == "click_01";
		}
		else if (entry.Loop)
		{
			StartIdleAnim();
		}
	}

	private void OnSpineAnimStart(IPartnerSequenceTrack entry)
	{
		string name = entry.Animation.Name;
		if (!(name == "idle_01"))
		{
			if (name == "click_01")
			{
				StartClickAnim();
			}
		}
		else
		{
			StartIdleAnim();
		}
	}

	private void StartIdleAnim()
	{
		ResetIdleAnim();
		ShowIdleEffect();
	}

	private void StartClickAnim()
	{
		ResetIdleAnim();
	}

	private void ResetIdleAnim()
	{
		DisposeIdleEffectCts();
		HideIdleEffect();
	}

	private void HideIdleEffect()
	{
		if (mIdleEffectInfoList == null || mIdleEffectInfoList.Count == 0)
		{
			return;
		}
		foreach (NpcDetailLiveEffectInfo mIdleEffectInfo in mIdleEffectInfoList)
		{
			if (!((Object)(object)mIdleEffectInfo.EffectObject == (Object)null))
			{
				mIdleEffectInfo.EffectObject.SetActive(false);
			}
		}
	}

	private void ShowIdleEffect()
	{

		if (mIdleEffectInfoList == null || mIdleEffectInfoList.Count == 0)
		{
			return;
		}
		mIdleEffectCts = new CancellationTokenSource();
		CancellationToken token = mIdleEffectCts.Token;
		foreach (NpcDetailLiveEffectInfo mIdleEffectInfo in mIdleEffectInfoList)
		{
			if (!((Object)(object)mIdleEffectInfo.EffectObject == (Object)null))
			{
				UniTaskExtensions.Forget(DelayShowEffect(mIdleEffectInfo, token));
			}
		}
	}

	private void DisposeIdleEffectCts()
	{
		if (mIdleEffectCts != null)
		{
			mIdleEffectCts.Cancel();
			mIdleEffectCts.Dispose();
			mIdleEffectCts = null;
		}
	}

	private void OnNpcLiveClicked()
	{
		if (!(services.Resolve(mNpcLiveGraphic).AnimationState.GetCurrent(0).Animation.Name == "click_01"))
		{
			ShowClickEffects(isShow: false);
			services.PlayAnimation(mNpcLiveGraphic, "click_01", loop: false, 0.25f, endResumeLast: true);
			ShowClickEffects(isShow: true);
		}
	}

	private void ShowClickEffects(bool isShow)
	{

		DisposeClickEffectCts();
		if (!isShow)
		{
			foreach (NpcDetailLiveEffectInfo mClickEffectInfo in mClickEffectInfoList)
			{
				mClickEffectInfo.EffectObject.SetActive(false);
			}
			return;
		}
		mClickEffectCts = new CancellationTokenSource();
		CancellationToken token = mClickEffectCts.Token;
		foreach (NpcDetailLiveEffectInfo mClickEffectInfo2 in mClickEffectInfoList)
		{
			if (mClickEffectInfo2.MillisecondsDelay > 0)
			{
				UniTaskExtensions.Forget(DelayShowEffect(mClickEffectInfo2, token));
			}
			else
			{
				mClickEffectInfo2.EffectObject.SetActive(true);
			}
		}
	}

    private async UniTask DelayShowEffect(NpcDetailLiveEffectInfo info, CancellationToken cancellationToken)
    {
        try
        {
            await UniTask.Delay(info.MillisecondsDelay, false, (PlayerLoopTiming)8, cancellationToken, false);
            info.EffectObject.SetActive(true);
        }
        catch (OperationCanceledException) { }
    }

	private void DisposeClickEffectCts()
	{
		if (mClickEffectCts != null)
		{
			mClickEffectCts.Cancel();
			mClickEffectCts.Dispose();
			mClickEffectCts = null;
		}
	}

	public void ShowNpc(int npcId)
	{



		mNpcInfo = services.GetNpcInfo(npcId);
		if (mNpcInfo == null)
		{
			Debug.LogError("NpcDetailLiveItem.ShowNpc error. can\'t get npcInfo. npcId = " + npcId);
			return;
		}
		bool flag = false;
		if (services.TryGetLiveImagePath(npcId, out var path))
		{
			mDisposableBag.Clear();
			ScriptableObject result = mDisposableBag.Add(services.LoadSkeleton("Assets/AppearanceAssets/NpcPortrait/" + path)).Result;
			if ((Object)(object)result != (Object)null)
			{
				services.SetSkeletonData(mNpcLiveGraphic, result);
				mNpcLiveRect.anchoredPosition = (Vector2)mNpcInfo.LiveOffset;
				((Transform)mNpcLiveRect).localScale = mNpcInfo.LiveScale;
				flag = true;
			}
		}
		if (!flag && !services.HasSkeletonData(mNpcLiveGraphic))
		{
			Debug.LogError("NpcDetailLiveItem.ShowNpc error. npcId=" + npcId + " 未配置 FullBodyLiveImage，且预制体 skeletonDataAsset 为空");
		}
		else
		{
			((Component)mNpcLiveRect).gameObject.SetActive(true);
			services.Initialize(mNpcLiveGraphic, true);
		}
	}
}

}
